// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner initially address(0) – deployer is not owner
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (correct): require(msg.sender == owner) fails because nonOwner != address(0), so reverts => ok false
        // Buggy: require(msg.sender != owner) passes because nonOwner != address(0), so does not revert => ok true
        assertTrue(ok == false, "Call should revert when msg.sender is not owner");
    }
}
